INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2018-01-01-us-federal-ipp-mandate', 'en', 'Federal B2G e-invoicing required since 2018, but format was never mandated', 'Following a 2015 OMB directive, US federal agencies moved to electronic invoicing for appropriate procurements via the Treasury''s Invoice Processing Platform by the end of FY2018 — but unlike many countries in this tracker, no specific e-invoice format or delivery method was ever mandated.', '<h3>🇺🇸 Federal B2G e-invoicing required since 2018, but format was never mandated</h3>
<p>Following a 2015 Office of Management and Budget directive, US federal agencies were required to move toward electronic invoicing for appropriate federal procurements, a transition largely completed by the end of FY2018. The Treasury Department''s Invoice Processing Platform (IPP), run by the Bureau of the Fiscal Service, has become the central mechanism for this — a free, web-based service handling the invoicing process from purchase order through payment notification, available to any federal agency and its vendors at no cost.</p>
<p>Worth understanding what makes the US approach genuinely different from most other countries in this tracker: the federal directive required agencies to move to electronic invoicing, but never specified a mandatory format or delivery method for doing so. This is a real contrast with, for example, Canada''s approach — where federal suppliers must use one specific platform (SAP Ariba) in one specific format (Peppol BIS or UBL-XML). That format flexibility in the US likely contributed to slower, more fragmented adoption than a single mandated standard would have produced, even though the underlying push toward electronic invoicing has been in place for years.</p>
<p><strong>What this means for your team:</strong> if you supply US federal agencies, confirm which specific agencies you work with actually require IPP, since — unlike Canada''s single-platform approach — requirements can genuinely vary by agency rather than following one uniform federal standard. Don''t assume "the federal government requires e-invoicing" translates into one specific format or platform requirement across every agency you deal with.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2024-04-11-us-eu-joint-declaration', '2024-04-11', '2024-04', 'The US federal government and the European Union announced a joint declaration on increased collaboration and interoperability in electronic invoicing, involving the White House directly and signalling growing US policy attention to a space historically left almost entirely to market forces.', '<h3>🇺🇸 US and EU announce joint collaboration on e-invoicing interoperability</h3>
<p>Until relatively recently, the US federal government had made little coordinated effort to promote e-invoicing beyond the existing, format-flexible B2G requirement — a natural consequence of the US having no federal VAT system, which removes the tax-fraud-prevention motivation that has driven so much government-led e-invoicing adoption elsewhere. That changed with the announcement of a joint EU-US declaration on increased collaboration and interoperability in electronic invoicing, involving the White House directly alongside the federal government.</p>
<p>This matters specifically for US businesses trading with EU counterparts, who face their own accelerating e-invoicing requirements under the EU''s ViDA framework and various national mandates already covered elsewhere in this tracker. Genuine interoperability between US exchange approaches (largely EDI and the newer DBNAlliance network) and EU standards like Peppol and EN 16931 reduces the risk of US exporters needing entirely separate, incompatible systems just to trade with European partners.</p>
<p><strong>What this means for your team:</strong> if your business exports to or otherwise trades regularly with EU counterparts, this declaration is worth watching as a signal that US-EU interoperability is a genuine, actively pursued policy goal rather than something left purely to individual software vendors to solve. Software capable of formatting US invoices into Peppol/BIS or country-specific EU XML formats will matter increasingly for smooth cross-border trade, even without any change to the absence of a domestic US mandate.</p>', 'https://fiscal.treasury.gov/ipp/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2024-04-11-us-eu-joint-declaration', id FROM countries WHERE name_en = 'United States';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2024-04-11-us-eu-joint-declaration', 'en', 'US and EU announce joint collaboration on e-invoicing interoperability', 'The US federal government and the European Union announced a joint declaration on increased collaboration and interoperability in electronic invoicing, involving the White House directly and signalling growing US policy attention to a space historically left almost entirely to market forces.', '<h3>🇺🇸 US and EU announce joint collaboration on e-invoicing interoperability</h3>
<p>Until relatively recently, the US federal government had made little coordinated effort to promote e-invoicing beyond the existing, format-flexible B2G requirement — a natural consequence of the US having no federal VAT system, which removes the tax-fraud-prevention motivation that has driven so much government-led e-invoicing adoption elsewhere. That changed with the announcement of a joint EU-US declaration on increased collaboration and interoperability in electronic invoicing, involving the White House directly alongside the federal government.</p>
<p>This matters specifically for US businesses trading with EU counterparts, who face their own accelerating e-invoicing requirements under the EU''s ViDA framework and various national mandates already covered elsewhere in this tracker. Genuine interoperability between US exchange approaches (largely EDI and the newer DBNAlliance network) and EU standards like Peppol and EN 16931 reduces the risk of US exporters needing entirely separate, incompatible systems just to trade with European partners.</p>
<p><strong>What this means for your team:</strong> if your business exports to or otherwise trades regularly with EU counterparts, this declaration is worth watching as a signal that US-EU interoperability is a genuine, actively pursued policy goal rather than something left purely to individual software vendors to solve. Software capable of formatting US invoices into Peppol/BIS or country-specific EU XML formats will matter increasingly for smooth cross-border trade, even without any change to the absence of a domestic US mandate.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-15-us-no-mandate-practical-requirements', '2026-01-15', '2026-01', 'With no federal B2B e-invoicing mandate in the US, businesses can still send invoices by PDF, email, EDI, or structured format freely — but IRS guidance requires electronic invoice records to remain accessible, accurate, legible, and retrievable, with a standard 7-year retention period.', '<h3>🇺🇸 No B2B mandate exists, but real record-keeping requirements still apply</h3>
<p>Heading into 2026, it''s worth being precise about what actually is and isn''t required for US businesses: there remains no nationwide B2B e-invoicing mandate of any kind. A business can send invoices by PDF, email, EDI, portal upload, or genuinely structured electronic format, entirely according to whatever a given customer relationship or trading agreement calls for — there''s no single government platform or format requirement to satisfy, unlike the great majority of countries covered elsewhere in this tracker.</p>
<p>That absence of a mandate doesn''t mean an absence of requirements entirely, though. IRS Publication 583 makes clear that the same record-keeping standards applying to paper books and records apply equally to electronic storage systems — invoice records must remain accessible, accurate, legible, and retrievable throughout the required retention period, which runs 7 years as a standard baseline. Electronic storage is explicitly permitted, but "permitted" isn''t the same as "unregulated" — the underlying integrity and retrievability standards still apply regardless of format.</p>
<p><strong>What this means for your team:</strong> don''t mistake "no e-invoicing mandate" for "no compliance requirements at all" — your actual obligation is ensuring whatever electronic invoices you already send or receive remain genuinely accessible and legible for the full 7-year window, not just stored somewhere. This is also a genuinely good moment to build real e-invoicing capability voluntarily, given how many trading partners — across the EU, India, Mexico, Brazil, and elsewhere in this tracker — already require it on their end, even without any US mandate forcing the issue domestically.</p>', 'https://fiscal.treasury.gov/ipp/', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-15-us-no-mandate-practical-requirements', id FROM countries WHERE name_en = 'United States';
